<script setup>
import { nextTick, onMounted, ref } from 'vue'
import { api, streamConversation } from '../api'
import { llmStatusLabel, publishCapabilities } from '../capabilities'
import { Bot, ChevronDown, CircleStop, MessageSquarePlus, Pencil, Send, Trash2 } from 'lucide-vue-next'
import { emitMotion } from '../motion'
import ChatParticleField from '../components/ChatParticleField.vue'

const isDemo = import.meta.env.MODE === 'demo'
const conversations=ref([]),activeId=ref(''),messages=ref([]),input=ref(''),loading=ref(true),sending=ref(false),error=ref(''),status=ref(''),scroller=ref(),controller=ref(),capabilities=ref(null),activeAgent=ref('idle'),lastQuery=ref(''),motionPulse=ref(0)
let createPromise=null, initializationPromise=null
async function loadConversations(selectFirst=true){const data=await api.conversations.list();conversations.value=data.items;if(selectFirst&&!activeId.value&&data.items.length)await select(data.items[0].id)}
async function createConversation(){if(createPromise)return createPromise;createPromise=(async()=>{const item=await api.conversations.create();if(!conversations.value.some(x=>x.id===item.id))conversations.value.unshift(item);await select(item.id);return item})();try{return await createPromise}finally{createPromise=null}}
async function select(id){if(sending.value)return;activeId.value=id;loading.value=true;error.value='';try{messages.value=(await api.conversations.messages(id)).items}catch(e){error.value=e.message}finally{loading.value=false;scrollBottom()}}
async function rename(item){const title=window.prompt('输入新的会话名称',item.title);if(!title?.trim())return;await api.conversations.rename(item.id,title.trim());item.title=title.trim()}
async function remove(item){if(!window.confirm(`删除会话“${item.title}”？`))return;await api.conversations.remove(item.id);conversations.value=conversations.value.filter(x=>x.id!==item.id);if(activeId.value===item.id){activeId.value='';messages.value=[];if(conversations.value.length)await select(conversations.value[0].id)}}
function scrollBottom(){nextTick(()=>{if(scroller.value)scroller.value.scrollTop=scroller.value.scrollHeight})}
async function send(){const text=input.value.trim();if(!text||sending.value)return;if(initializationPromise)await initializationPromise;if(!activeId.value)await createConversation();input.value='';sending.value=true;error.value='';status.value='准备中';activeAgent.value='orchestrator';lastQuery.value=text;motionPulse.value+=1;messages.value.push({role:'user',content:text});const assistant={role:'assistant',content:'',metadata:{references:[],trace:[],recipe:null,recipes:[]},streaming:true};messages.value.push(assistant);controller.value=new AbortController();emitMotion('agent',{label:'orchestrator'});scrollBottom()
  try{await streamConversation(activeId.value,text,(event)=>{if(event.type==='status'){status.value=event.message;activeAgent.value=event.agent||'system';motionPulse.value+=1;assistant.metadata.trace.push({agent:event.agent||'system',message:event.message,elapsed_ms:event.elapsed_ms});emitMotion('agent',{label:event.agent||'system'})}else if(event.type==='agent_event'){activeAgent.value=event.agent||'system';motionPulse.value+=1;assistant.metadata.trace.push({agent:event.agent,message:event.message,elapsed_ms:event.elapsed_ms});emitMotion('agent',{label:event.agent||'agent'})}else if(event.type==='partial'){activeAgent.value='stream';assistant.content+=event.text;if(assistant.content.length===event.text.length||assistant.content.length%180<event.text.length){motionPulse.value+=1;emitMotion('stream',{label:'partial'})}}else if(event.type==='reference'){assistant.metadata.references=event.references||[]}else if(event.type==='done'){activeAgent.value='done';motionPulse.value+=1;assistant.content=event.answer||assistant.content;assistant.metadata.references=event.references||[];assistant.metadata.recipe=event.recipe;assistant.metadata.recipes=event.recipes||[];assistant.metadata.creative_brief=event.creative_brief||{};assistant.metadata.capability_mode=event.capability_mode||'model';assistant.metadata.retrieval=event.retrieval||{};if(!assistant.metadata.trace.length)assistant.metadata.trace=event.agent_trace||[];assistant.metadata.trace_id=event.trace_id;status.value='';emitMotion('complete',{label:event.trace_id||'answer'})}else if(event.type==='error'){activeAgent.value='idle';emitMotion('error',{label:'chat'});throw new Error(event.message)}scrollBottom()},controller.value.signal);await loadConversations(false)}catch(e){activeAgent.value='idle';if(e.name==='AbortError'){assistant.content=assistant.content||'已停止生成。'}else{assistant.content=assistant.content||'这次没有完成。';assistant.error=e.message;emitMotion('error',{label:e.name||'chat'})}}finally{assistant.streaming=false;sending.value=false;controller.value=null;status.value='';refreshCapabilities();scrollBottom()}}
function stop(){controller.value?.abort()}
const roleNames={system:'协调任务',orchestrator:'理解需求',retriever:'检索配方与知识',stock:'核对酒柜',flavor:'分析风味',tutor:'拆解调制方法',reviewer:'复核答案',brief:'需求分析',evidence:'结构参考',create:'原创配方设计',rules:'比例与技法校验',revise:'定向修订',review:'独立吧台审校',ready:'最终确认'}
function roleName(name){return roleNames[name]||'协作处理'}
const capabilityLabels={model:'本轮由模型理解并生成',model_grounded:'模型生成 · 本地证据与规则约束',model_unreviewed:'模型生成 · 独立审校未完成',model_partial:'模型参与 · 部分能力不可用',local_parser:'仅解析明确约束 · 未执行模型推理',local_retrieval:'本轮由本地证据检索回答',local_inventory:'本轮由库存规则匹配',local_rules:'本轮由本地规则创作并复核',local_grounded:'本轮由本地证据与规则协同',local_unreviewed:'本地证据回答 · 模型审校未完成',local_partial:'本地能力回答 · 部分能力不可用',model_rules_review:'本轮由模型创作、本地规则复核',unavailable:'本轮智能能力不可用'}
function capabilityLabel(mode){return capabilityLabels[mode]||''}
function referenceSource(ref){return ref.source_type==='cocktails'?'配方库':ref.source_type==='knowledge'?'知识卡':'来源'}
const ingredientNames={gin:'金酒',vodka:'伏特加',rum:'朗姆酒',whiskey:'威士忌',tequila:'龙舌兰',brandy:'白兰地','tonic water':'汤力水',honey:'蜂蜜','egg white':'蛋清'}
function ingredientName(value){return ingredientNames[value]||value}
function creativeBriefItems(brief){if(!brief||typeof brief!=='object')return[];const items=[];const add=(label,value)=>{if(value)items.push({label,value})};add('甜度',brief.sweetness);add('酸度',brief.acidity);add('酒感',brief.alcohol);add('基酒',(brief.base_spirits||[]).map(ingredientName).join('、'));add('形态',brief.serve_style);add('场景',brief.occasion);add('不用',(brief.avoid_ingredients||[]).map(ingredientName).join('、'));return items}
function imageUrl(recipe){const url=recipe?.image||'';return url.includes('thecocktaildb.com')&&!url.endsWith('/preview')?`${url}/preview`:url}
function hideBrokenImage(event){const frame=event.currentTarget.parentElement;frame.hidden=true;frame.closest('.recommendation-card')?.classList.remove('has-art')}
function showLoadedImage(event){const frame=event.currentTarget.parentElement;frame.hidden=false;frame.closest('.recommendation-card')?.classList.add('has-art')}
async function refreshCapabilities(){try{capabilities.value=await api.capabilities();publishCapabilities(capabilities.value)}catch(_){}}
onMounted(()=>{refreshCapabilities();initializationPromise=(async()=>{try{await loadConversations();if(!conversations.value.length)await createConversation()}catch(e){error.value=e.message}finally{loading.value=false;initializationPromise=null}})()})
</script>
<template>
<div class="chat-layout" :class="{ 'demo-chat': isDemo }">
  <aside class="conversation-pane">
    <div class="conversation-head"><strong>会话</strong><button class="icon-btn" title="新建会话" @click="createConversation"><MessageSquarePlus :size="18"/></button></div>
    <div class="conversation-list">
      <button v-for="item in conversations" :key="item.id" :class="{active:item.id===activeId}" @click="select(item.id)"><span>{{item.title}}</span><small>{{item.updated_at?.slice(0,10)}}</small><i><Pencil :size="14" @click.stop="rename(item)"/><Trash2 :size="14" @click.stop="remove(item)"/></i></button>
    </div>
  </aside>
  <section class="chat-main">
    <ChatParticleField :active="sending" :phase="activeAgent" :seed="lastQuery" :pulse="motionPulse" />
    <header><div><h1>AI 调酒台</h1><p>{{ isDemo ? '输入酒名、材料或无酒精等偏好，匹配本地演示配方。' : '检索、库存、风味与教学 Agent 按问题复杂度协作' }}</p></div><span v-if="capabilities&&!capabilities.llm?.available" class="capability-mode" title="模型不可用时，库存匹配与配方检索仍使用本地真实数据">{{llmStatusLabel(capabilities.llm)}}</span><select class="select mobile-conversation" v-model="activeId" @change="select(activeId)"><option v-for="item in conversations" :key="item.id" :value="item.id">{{item.title}}</option></select></header>
    <div ref="scroller" class="message-list">
      <div v-if="loading" class="state">正在读取会话...</div><div v-else-if="error" class="state"><div><strong>会话加载失败</strong>{{error}}</div></div>
      <div v-else-if="!messages.length" class="chat-empty"><span><Bot :size="29"/></span><h2>今晚想喝什么？</h2><p>直接告诉我你的口味、材料或场景，我会结合上下文继续聊。</p></div>
      <article v-for="(message,index) in messages" :key="message.id||index" class="message" :class="message.role">
        <div class="message-avatar">{{message.role==='user'?'我':'AI'}}</div><div class="message-content"><p>{{message.content}}<span v-if="message.streaming&&!message.content" class="typing">正在组织答案</span></p><small v-if="capabilityLabel(message.metadata?.capability_mode)" class="answer-mode">{{capabilityLabel(message.metadata.capability_mode)}}</small><section v-if="creativeBriefItems(message.metadata?.creative_brief).length&&!message.metadata?.recipe" class="creative-brief"><header><span>共同创作简报</span><small>随对话实时更新</small></header><div><span v-for="item in creativeBriefItems(message.metadata.creative_brief)" :key="item.label"><b>{{item.label}}</b>{{item.value}}</span></div></section><div v-if="message.error" class="error-box">{{message.error}}</div>
          <section v-if="message.metadata?.recipes?.length > 1" class="recommendation-set">
            <header><div><small>根据本轮条件筛选</small><strong>{{ message.metadata.recipes.length }} 款不同推荐</strong></div><span>按匹配度排列</span></header>
            <div class="recommendation-list"><router-link v-for="(recipe,i) in message.metadata.recipes" :key="recipe.id||recipe.name" :to="recipe.id?`/recipes/${recipe.id}`:'/explore'" class="recommendation-card" :style="{ '--order': i }">
              <div v-if="imageUrl(recipe)" class="recommendation-art" hidden><img :src="imageUrl(recipe)" :alt="`${recipe.name_cn||recipe.name} 成品图`" @load="showLoadedImage" @error="hideBrokenImage"/></div>
              <div class="recommendation-copy"><small>0{{i+1}}</small><h3>{{recipe.name_cn||recipe.name}}</h3><p v-if="recipe.name_cn&&recipe.name_cn!==recipe.name">{{recipe.name}}</p><div><span>{{recipe.method||'按原配方调制'}}</span><span>约 {{recipe.abv||0}}% ABV</span></div></div>
            </router-link></div>
          </section>
          <section v-if="message.metadata?.recipe" class="inline-recipe">
            <div class="recipe-answer-head"><div><small>本轮推荐</small><strong>{{message.metadata.recipe.name_cn||message.metadata.recipe.name}}</strong><span v-if="message.metadata.recipe.name_cn && message.metadata.recipe.name_cn!==message.metadata.recipe.name">{{message.metadata.recipe.name}}</span></div><router-link v-if="message.metadata.recipe.id" class="btn" :to="`/recipes/${message.metadata.recipe.id}`">查看详情</router-link></div>
            <div class="recipe-facts"><span>{{message.metadata.recipe.method||'按原配方调制'}}</span><span>{{message.metadata.recipe.glass||'杯具未注明'}}</span><span v-if="message.metadata.recipe.abv!==null && message.metadata.recipe.abv!==undefined">约 {{message.metadata.recipe.abv}}% ABV</span></div>
            <div class="recipe-guide">
              <div><h4>材料</h4><ul><li v-for="(item,i) in message.metadata.recipe.ingredients||[]" :key="i"><span>{{item.name}}</span><b>{{item.amount||'适量'}}</b></li></ul></div>
              <div><h4>分步调制</h4><ol><li v-for="(step,i) in message.metadata.recipe.steps||[]" :key="i"><span>{{i+1}}</span><p>{{step}}</p></li></ol></div>
            </div>
            <p v-if="message.metadata.recipe.tips" class="recipe-tip">{{message.metadata.recipe.tips}}</p>
          </section>
          <details v-if="message.metadata?.references?.length" class="references"><summary><ChevronDown :size="14"/>配方与知识来源 · {{message.metadata.references.length}}</summary><div><component :is="ref.url?'a':'span'" v-for="ref in message.metadata.references" :key="ref.id||ref.title" class="reference-item" :href="ref.url||undefined" :target="ref.url?'_blank':undefined" :rel="ref.url?'noreferrer':undefined"><b>{{ref.title}}</b><small>{{referenceSource(ref)}} · v{{ref.version||1}}<template v-if="ref.score!==null&&ref.score!==undefined"> · {{Number(ref.score).toFixed(2)}}</template></small></component></div></details>
          <details v-if="message.metadata?.trace?.length" class="trace"><summary><ChevronDown :size="14"/>查看本次协作过程 · {{message.metadata.trace.length}} 步</summary><ol><li v-for="(event,i) in message.metadata.trace" :key="i"><b>{{roleName(event.agent)}}</b><span>{{event.message}}</span></li></ol></details>
        </div>
      </article>
    </div>
    <footer class="composer"><div v-if="status" class="stream-status">{{status}}</div><div class="composer-row"><textarea v-model="input" rows="1" maxlength="2000" placeholder="描述口味、材料或场景..." :disabled="loading" @keydown.enter.exact.prevent="send"></textarea><button v-if="sending" class="send stop" title="停止生成" @click="stop"><CircleStop :size="20"/></button><button v-else class="send" title="发送" :disabled="!input.trim()||loading" @click="send"><Send :size="19"/></button></div><small>仅向成年人提供建议。饮酒请适量，酒后请勿驾驶。</small></footer>
  </section>
</div>
</template>
