  .chat-main{position:relative;isolation:isolate;height:100vh;display:grid;grid-template-rows:auto minmax(0,1fr) auto;min-width:0}.chat-main>header,.message-list,.composer{position:relative;z-index:1}.chat-main>header{padding:21px 28px 16px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.82);display:flex;justify-content:space-between;align-items:center;gap:14px}.chat-main h1{font-size:20px;margin:0}.chat-main header p{font-size:12px;color:var(--muted);margin:4px 0 0}.capability-mode{margin-left:auto;padding:5px 8px;border:1px solid #d19a3f;background:#fff7e9;color:#76521d;border-radius:4px;font-size:10px;font-weight:700;white-space:nowrap}.mobile-conversation{display:none}.message-list{overflow-y:auto;padding:24px max(24px,calc((100% - 820px)/2));scroll-behavior:smooth;background:rgba(247,246,242,.46)}.chat-empty{text-align:center;margin:auto;padding:12vh 20px;color:var(--muted)}.chat-empty>span{width:58px;height:58px;border-radius:50%;background:#e5eee8;color:var(--green);display:grid;place-items:center;margin:auto}.chat-empty h2{color:var(--ink);font-size:23px;margin:17px 0 5px}.message{display:grid;grid-template-columns:34px minmax(0,1fr);gap:11px;margin-bottom:22px}.message.user{margin-left:15%}.message-avatar{width:32px;height:32px;border-radius:6px;background:#dbe2dd;display:grid;place-items:center;font-size:11px;font-weight:800}.message.assistant .message-avatar{background:var(--green);color:#fff}.message-content{min-width:0}.message-content>p{white-space:pre-wrap;line-height:1.72;margin:3px 0 10px;font-size:14px}.message.user .message-content>p{background:#fff;border:1px solid var(--line);border-radius:8px;padding:11px 13px;display:inline-block}.answer-mode{display:block;color:var(--muted);font-size:10px;margin:-3px 0 10px}.typing{color:var(--muted)}.typing:after{content:'...';animation:pulse 1.1s infinite}@keyframes pulse{50%{opacity:.25}}.references{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.references small{color:var(--muted)}.trace{margin-top:10px;font-size:12px;color:var(--muted)}.trace summary{display:flex;align-items:center;gap:5px;cursor:pointer}.trace ol{list-style:none;padding:8px 0 0 3px;margin:0;border-left:1px solid var(--line)}.trace li{display:grid;grid-template-columns:125px minmax(0,1fr);gap:7px;padding:5px 0 5px 10px}.trace li b{color:#46504a}.inline-recipe{display:flex;flex-wrap:wrap;align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:7px;padding:12px}.inline-recipe span{color:var(--muted);font-size:12px;margin-right:auto}.inline-recipe .btn{min-height:31px;font-size:11px}
