.message{display:flex;width:100%;align-items:flex-start;gap:10px;margin:0 0 22px}.message.user{width:fit-content;max-width:88%;margin-left:auto;flex-direction:row-reverse}.message-avatar{flex:0 0 32px}.message-content{width:auto;max-width:min(80%,760px)}.message.user .message-content{display:flex;flex-direction:column;align-items:flex-end;max-width:calc(100% - 42px)}.message-content>p{display:inline-block;background:#fff;border:1px solid var(--line);border-radius:8px;padding:11px 13px;margin:0 0 10px}.message.user .message-content>p{background:var(--green);border-color:var(--green);color:#fff}.message.assistant .message-content>p{border-top-left-radius:2px}.message.user .message-content>p{border-top-right-radius:2px}.message.user .error-box{align-self:flex-end}.inline-recipe{width:min(100%,760px);margin-top:8px;border-left:3px solid var(--amber);background:#fff;padding:15px 16px}.recipe-answer-head{display:flex;justify-content:space-between;align-items:center;gap:14px}.recipe-answer-head>div{display:grid;gap:2px}.recipe-answer-head small{color:var(--amber);font-weight:700}.recipe-answer-head strong{font-size:18px}.recipe-answer-head span{font-size:11px;color:var(--muted)}.recipe-facts{display:flex;flex-wrap:wrap;gap:7px;margin:12px 0}.recipe-facts span{background:#edf2ee;color:#345444;padding:5px 8px;border-radius:4px;font-size:11px}.recipe-guide{display:grid;grid-template-columns:minmax(180px,.75fr) minmax(260px,1.25fr);gap:20px;border-top:1px solid var(--line);padding-top:13px}.recipe-guide h4{font-size:13px;margin:0 0 9px}.recipe-guide ul,.recipe-guide ol{list-style:none;padding:0;margin:0;display:grid;gap:7px}.recipe-guide ul li{display:flex;justify-content:space-between;gap:12px;font-size:12px}.recipe-guide ul li b{font-weight:600;text-align:right;color:var(--muted)}.recipe-guide ol li{display:grid;grid-template-columns:22px 1fr;gap:8px;align-items:start}.recipe-guide ol li>span{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:var(--green);color:#fff;font-size:11px}.recipe-guide ol p{margin:1px 0;font-size:12px;line-height:1.55}.recipe-tip{margin:12px 0 0!important;padding:9px 10px!important;border:0!important;border-left:2px solid var(--amber)!important;border-radius:0!important;background:#fff7e9!important;color:#73501e;font-size:11px!important}.references,.trace{max-width:760px}
.recommendation-set{width:min(100%,760px);margin:8px 0 12px;border-top:1px solid var(--line);padding-top:14px}.recommendation-set>header{display:flex;justify-content:space-between;align-items:end;margin-bottom:10px}.recommendation-set>header div{display:grid;gap:3px}.recommendation-set>header small{font-size:10px;color:var(--amber);font-weight:700}.recommendation-set>header strong{font-size:16px}.recommendation-set>header>span{font-size:10px;color:var(--muted)}.recommendation-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.recommendation-card{display:grid;grid-template-columns:1fr;min-height:105px;background:#fff;border:1px solid var(--line);border-radius:6px;overflow:hidden;animation:recommendation-in .42s both;animation-delay:calc(var(--order) * 65ms);transition:transform .2s,border-color .2s}.recommendation-card.has-art{grid-template-columns:92px 1fr}.recommendation-card:hover{transform:translateY(-2px);border-color:#87a294}.recommendation-art{position:relative;background:#dfe8e1;overflow:hidden}.recommendation-art img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.recommendation-copy{padding:10px;min-width:0}.recommendation-copy>small{color:var(--amber);font-size:9px;font-weight:800}.recommendation-copy h3{font-size:14px;margin:4px 0 1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.recommendation-copy>p{font-size:9px;color:var(--muted);margin:0 0 9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.recommendation-copy>div{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}.recommendation-copy span{font-size:9px;color:#456052;background:#edf2ee;padding:3px 5px;border-radius:3px}@keyframes recommendation-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
.creative-brief{width:min(100%,760px);margin:2px 0 12px;padding:12px 13px;border:1px solid #cbd9d0;border-left:3px solid var(--green);background:#f7fbf8;border-radius:5px}.creative-brief header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:9px}.creative-brief header span{font-size:12px;font-weight:750;color:#294e3b}.creative-brief header small{font-size:9px;color:var(--muted)}.creative-brief>div{display:flex;flex-wrap:wrap;gap:6px}.creative-brief>div>span{display:inline-flex;gap:5px;align-items:center;padding:5px 7px;background:#fff;border:1px solid #dbe4de;border-radius:4px;font-size:10px;color:#4c5851}.creative-brief b{color:var(--green);font-weight:750}
.references{display:block;margin-top:10px;color:var(--muted);font-size:11px}.references summary{display:flex;align-items:center;gap:5px;width:max-content;cursor:pointer}.references[open] summary svg{transform:rotate(180deg)}.references>div{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.reference-item{display:grid;gap:2px;min-width:120px;padding:6px 8px;border:1px solid var(--line);border-radius:4px;background:#fff;color:var(--ink)}.reference-item b{font-size:10px}.reference-item small{font-size:9px;color:var(--muted)}a.reference-item:hover{border-color:#87a294;color:var(--green)}
@media(max-width:720px){.message-content{max-width:86%}.recipe-guide{grid-template-columns:1fr}.inline-recipe{padding:13px}.recipe-answer-head{align-items:flex-start}.recipe-answer-head .btn{min-height:32px;padding:0 9px}.recommendation-list{grid-template-columns:1fr}.recommendation-card.has-art{grid-template-columns:82px 1fr}.recommendation-set>header>span{display:none}}@media(prefers-reduced-motion:reduce){.recommendation-card{animation:none;transition:none}}
</style>
